import Testing
@_spi(Testing) import WGSL

// The scan Lexer::lexNumber's state machine records for a literal it accepted.
private func scan(_ text: [UInt8]) -> NumberLiteralScan {
    let isHex = text.count >= 2 && text[0] == UInt8(ascii: "0") && (text[1] == UInt8(ascii: "x") || text[1] == UInt8(ascii: "X"))
    let hasP = text.contains(UInt8(ascii: "p")) || text.contains(UInt8(ascii: "P"))
    var suffix = NumberLiteralSuffix.none
    switch text.last {
    case UInt8(ascii: "i"):
        suffix = .i
    case UInt8(ascii: "u"):
        suffix = .u
    case UInt8(ascii: "h"):
        suffix = .h
    case UInt8(ascii: "f"):
        suffix = !isHex || hasP ? .f : .none
    default:
        break
    }
    let body = suffix == .none ? text[...] : text.dropLast()
    let exponentMarks: [UInt8] = isHex ? [UInt8(ascii: "p"), UInt8(ascii: "P")] : [UInt8(ascii: "e"), UInt8(ascii: "E")]
    return NumberLiteralScan(
        start: 0,
        integral: isHex ? 2 : 0,
        end: text.count,
        suffix: suffix,
        isHex: isHex,
        hasFraction: body.contains(UInt8(ascii: ".")),
        hasExponent: body.contains { exponentMarks.contains($0) }
    )
}

private func literal(_ text: String) -> NumberLiteral {
    let bytes = Array(text.utf8)
    return NumberParsing.literal(ContiguousArray(bytes), scan(bytes))
}

private func utf16Token(_ text: String) -> (units: ContiguousArray<UInt16>, scan: NumberLiteralScan) {
    let bytes = Array(text.utf8)
    // A non-ASCII prefix and suffix around the token, as in a 16-bit source.
    var units: ContiguousArray<UInt16> = [0x4E2D, 0x20]
    units.append(contentsOf: bytes.map { UInt16($0) })
    units.append(contentsOf: [0x20, 0x6587])
    var tokenScan = scan(bytes)
    tokenScan.start += 2
    tokenScan.integral += 2
    tokenScan.end += 2
    return (units, tokenScan)
}

private func literalUTF16(_ text: String) -> NumberLiteral {
    let token = utf16Token(text)
    return NumberParsing.literal(token.units, token.scan)
}

// As the lexer converts every number of a 16-bit source: narrowed into the same buffer.
private func literalUTF16(_ text: String, reusing bytes: inout ContiguousArray<UInt8>) -> NumberLiteral {
    let token = utf16Token(text)
    return NumberParsing.literal(token.units, token.scan, &bytes)
}

private func hex16(_ bits: UInt64) -> String {
    let digits = String(bits, radix: 16)
    return String(repeating: "0", count: 16 - digits.utf8.count) + digits
}

// A "<kind> <payload>" vector.
private func describe(_ literal: NumberLiteral) -> String {
    switch literal {
    case .invalid:
        "X -"
    case .integerLiteral(let value):
        "I \(value)"
    case .integerLiteralSigned(let value):
        "i \(value)"
    case .integerLiteralUnsigned(let value):
        "u \(value)"
    case .abstractFloatLiteral(let value):
        "A " + hex16(value.bitPattern)
    case .floatLiteral(let value):
        "f " + hex16(Double(value).bitPattern)
    case .halfLiteral(let value):
        "h " + hex16(value.bitPattern)
    }
}

private func bits(_ literal: NumberLiteral) -> UInt64? {
    switch literal {
    case .abstractFloatLiteral(let value), .halfLiteral(let value):
        value.bitPattern
    case .floatLiteral(let value):
        Double(value).bitPattern
    case .invalid, .integerLiteral, .integerLiteralSigned, .integerLiteralUnsigned:
        nil
    }
}

private func parseDouble(_ text: String) -> (bits: UInt64, parsedLength: Int) {
    let bytes = ContiguousArray(text.utf8)
    var parsedLength = -1
    let value = NumberParsing.parseDouble(bytes, 0..<bytes.count, parsedLength: &parsedLength)
    return (value.bitPattern, parsedLength)
}

private func stringToDouble(_ text: String) -> Double? {
    let bytes = ContiguousArray(text.utf8)
    var parsedLength = -1
    guard let value = NumberParsing.stringToDouble(bytes, 0..<bytes.count, parsedLength: &parsedLength) else {
        #expect(parsedLength == 0)
        return nil
    }
    #expect(parsedLength == bytes.count)
    return value
}

private func parseInteger(_ text: String, base: UInt8) -> Int64? {
    let bytes = ContiguousArray(text.utf8)
    return NumberParsing.parseInteger(bytes, 0..<bytes.count, base: base)
}

@Suite
struct WGSLNumberParsingTests {
    // Decimal floats are range-checked as doubles, then narrowed once.
    @Test
    func decimalFloatRangeChecks() {
        #expect(literal("3.4028235e38f") == .invalid)
        #expect(literal("3.4028234e38f") == .floatLiteral(.greatestFiniteMagnitude))
        #expect(literal("65519h") == .invalid)
        #expect(literal("65504h") == .halfLiteral(65504))
        #expect(literal("65504.0000001h") == .invalid)
        #expect(bits(literal("1.00000005960464477539062500001f")) == Double(1).bitPattern)
        #expect(bits(literal("1e-400")) == 0)
        #expect(literal("1e400") == .invalid)
        #expect(literal("1.7976931348623158e308") == .abstractFloatLiteral(.greatestFiniteMagnitude))
        #expect(literal("1.7976931348623159e308") == .invalid)
        #expect(bits(literal("2.4703282292062328e-324")) == 1)
        #expect(bits(literal("2.4703282292062327e-324")) == 0)
        #expect(bits(literal("2.2250738585072011e-308")) == 0x000F_FFFF_FFFF_FFFF)
        #expect(bits(literal("0.1")) == 0x3FB9_9999_9999_999A)
        #expect(bits(literal(".5")) == 0x3FE0_0000_0000_0000)
        #expect(bits(literal("5.")) == 0x4014_0000_0000_0000)
        #expect(bits(literal("0e999999999999")) == 0)
    }

    // strtod's ERANGE (overflow, total underflow, inexact subnormal) makes the token Invalid.
    @Test
    func hexFloatRanges() {
        #expect(bits(literal("0x1p-1074")) == 1)
        #expect(literal("0x1p-1075") == .invalid)
        #expect(literal("0x1.8p-1074") == .invalid)
        #expect(literal("0x1p1024") == .invalid)
        #expect(literal("0x1.fffffffffffff8p1023") == .invalid)
        #expect(literal("0x1.fffffffffffff7p1023") == .abstractFloatLiteral(.greatestFiniteMagnitude))
        #expect(bits(literal("0x1.00000000000008p0")) == Double(1).bitPattern)
        #expect(bits(literal("0x1.00000000000018p0")) == 0x3FF0_0000_0000_0002)
        #expect(bits(literal("0x1.ffffffffffffe0p-1023")) == 0x000F_FFFF_FFFF_FFFF)
        #expect(literal("0x1.ffffffffffffe8p-1023") == .invalid)
        // An inexact subnormal that rounds up to the smallest normal is not ERANGE.
        #expect(bits(literal("0x1.fffffffffffff8p-1023")) == 0x0010_0000_0000_0000)
        #expect(literal("0x1p127f") == .floatLiteral(0x1p127))
        #expect(literal("0x1p128f") == .invalid)
        #expect(literal("0x1.ffcp15h") == .halfLiteral(65504))
        #expect(literal("0x1p16h") == .invalid)
        #expect(bits(literal("0x0p99999999999999")) == 0)
        #expect(literal("0x1p-1342177280") == .invalid)
        #expect(literal("0x1p+134217727") == .invalid)
    }

    @Test
    func integerRanges() {
        #expect(literal("9223372036854775807") == .integerLiteral(.max))
        #expect(literal("9223372036854775808") == .invalid)
        #expect(literal("0xFFFFFFFFFFFFFFFF") == .invalid)
        #expect(literal("0x7FFFFFFFFFFFFFFF") == .integerLiteral(.max))
        #expect(literal("2147483647i") == .integerLiteralSigned(.max))
        #expect(literal("2147483648i") == .invalid)
        #expect(literal("4294967295u") == .integerLiteralUnsigned(.max))
        #expect(literal("4294967296u") == .invalid)
        #expect(literal("0x1fu") == .integerLiteralUnsigned(31))
        #expect(literal("0i") == .integerLiteralSigned(0))
    }

    @Test
    func parseDoubleParsedLength() {
        #expect(parseDouble("1.5e") == (Double(1.5).bitPattern, 3))
        #expect(parseDouble("1.5f") == (Double(1.5).bitPattern, 3))
        #expect(parseDouble("+1") == (Double(1).bitPattern, 2))
        #expect(parseDouble("-0") == ((-0.0 as Double).bitPattern, 2))
        #expect(parseDouble("-") == (0, 0))
        #expect(parseDouble("") == (0, 0))
        #expect(parseDouble(".e1") == (0, 0))
        #expect(parseDouble("1e5x") == (Double(100_000).bitPattern, 3))
        #expect(parseDouble("1e+") == (Double(1).bitPattern, 1))
        #expect(parseDouble("1e400") == (Double.infinity.bitPattern, 5))
        #expect(parseDouble("inf") == (0, 0))
        #expect(parseDouble("nan") == (0, 0))
    }

    @Test
    func stringToDoubleHexadecimal() {
        #expect(stringToDouble("0x1.8p1") == 3)
        #expect(stringToDouble("0X.8P1") == 1)
        #expect(stringToDouble("0x1.") == 1)
        #expect(stringToDouble("0x1p-1075") == nil)
        #expect(stringToDouble("0x1p1024") == nil)
        #expect(stringToDouble("0x0.0p-99999") == 0)
    }

    @Test
    func parseIntegerTrailingJunk() {
        #expect(parseInteger(" \t12", base: 10) == 12)
        #expect(parseInteger("+5i", base: 10) == 5)
        #expect(parseInteger("-9223372036854775808", base: 10) == .min)
        #expect(parseInteger("-9223372036854775809", base: 10) == nil)
        #expect(parseInteger("9223372036854775808", base: 10) == nil)
        #expect(parseInteger("1fu", base: 16) == 31)
        #expect(parseInteger("ABCDEFg", base: 16) == 0xAB_CDEF)
        #expect(parseInteger("g", base: 16) == nil)
        #expect(parseInteger("a", base: 10) == nil)
        #expect(parseInteger("", base: 10) == nil)
        #expect(parseInteger("+-1", base: 10) == nil)
    }

    // Vectors from WTF::parseInteger, WTF::parseDouble and WTF::stringToDouble through the C++ lexer, so the check runs on
    // every OS that runs TestWGSL.
    @Test
    func vectorsFromWTF() {
        var count = 0
        var mismatches: [String] = []
        for line in numberParsingVectors.split(separator: "\n") {
            let fields = line.split(separator: " ")
            guard fields.count == 3 else {
                mismatches.append("malformed vector: \(line)")
                continue
            }
            let text = String(fields[0])
            let expected = fields[1] + " " + fields[2]
            let latin1 = describe(literal(text))
            let utf16 = describe(literalUTF16(text))
            if latin1 != expected || utf16 != expected {
                mismatches.append("\(text): expected \(expected), Latin-1 \(latin1), UTF-16 \(utf16)")
            }
            count += 1
        }
        #expect(count >= 10_000)
        #expect(mismatches.isEmpty, "\(mismatches.count) mismatches, first: \(mismatches.prefix(10))")
    }

    // The lexer narrows every number of a 16-bit source into one buffer: each token reads none of what longer ones left.
    @Test
    func utf16LiteralsReuseOneBuffer() {
        var bytes = ContiguousArray<UInt8>()
        var count = 0
        var mismatches: [String] = []
        for line in numberParsingVectors.split(separator: "\n") {
            let fields = line.split(separator: " ")
            guard fields.count == 3 else {
                continue
            }
            let text = String(fields[0])
            let expected = fields[1] + " " + fields[2]
            let reused = describe(literalUTF16(text, reusing: &bytes))
            if reused != expected {
                mismatches.append("\(text): expected \(expected), UTF-16 with a reused buffer \(reused)")
            }
            count += 1
        }
        #expect(count >= 10_000)
        #expect(mismatches.isEmpty, "\(mismatches.count) mismatches, first: \(mismatches.prefix(10))")
    }
}

